// One item per Iterable message-event type; the HTTP node runs once per item.
// 25h, NOT the cron interval. The trigger only fires 09:00-15:00 MT, so the
// gap between the last fire of one day and the first of the next is ~18h — a
// 90m lookback would have silently dropped every event in it. Re-reading the
// same events every run is free: /api/outcomes is idempotent per
// (recommendation_id, source) and _apply_flags never lets a null erase a
// measured value, so the 7th run of the day just rewrites the same rows.
// ponytail: fixed 25h window rather than tracking the last successful run.
// Ceiling: one day of events per export call, trivial at ~50 sends/day.
// Upgrade path: track a watermark if the export ever gets slow.
const LOOKBACK_MIN = 25 * 60;
const end = new Date();
const start = new Date(end.getTime() - LOOKBACK_MIN * 60000);
const fmt = (d) => d.toISOString().slice(0, 19).replace('T', ' '); // ASSUMPTION: Iterable project timezone is UTC.
return [
  'emailSend', 'emailOpen', 'emailClick', 'emailUnsubscribe',
  'smsSend', 'smsClick', 'smsUnsubscribe',
].map((dataTypeName) => ({ json: { dataTypeName, startDateTime: fmt(start), endDateTime: fmt(end) } }));

// Merge every message event in the window into ONE outcome row per (lcmRun, userId).
// That pair is (run_id, pro_id) — uq_winners_run_pro makes it exactly one Waypoint winner.
// Option C: start from what WE shipped, not from everything Iterable did.
// The work list is Waypoint's own funnel detail — every Pro that reached a
// verdict in the window. Only winners that were actually handed off could
// possibly have been sent, so anything else in the Iterable window is not ours
// and is dropped here instead of being POSTed as an unattributable row.
const WORKLIST = 'Waypoint work list';
const shipped = new Set(
  $(WORKLIST).all()
    .flatMap((i) => (i.json && i.json.pros) || [])
    .filter((p) => p.verdict === 'winner' && p.handed_off)
    .map((p) => p.run_id + '|' + p.pro_id)
);
if (!shipped.size) return [];  // nothing shipped in the window => nothing to match

const INTERNAL = ['allison.torres', 'jake.fassora', 'liann.bielicki']; // WAYPOINT_TEST_RECIPIENTS in the LCM app
const CHUNK = 500; // ponytail: fixed batch cap. Ceiling: one POST body per 500 rows. Upgrade path: lower it if Railway rejects the body size.

// Normalise to a real ISO instant. TWO traps here:
//   * `new Date("2026-08-20 10:00:00")` is VALID in V8 and is read in the
//     PROCESS-LOCAL zone, so a parse-then-fallback never reaches the 'Z' branch
//     for exactly the format we expect. settings.timezone governs cron
//     expressions, not `new Date()` inside a Code node. Offset FIRST.
//   * Iterable writes the offset after a SPACE ("... 10:00:00 +00:00"), and
//     replace(' ', 'T') only replaces the FIRST space — leaving an unparseable
//     "10:00:00 +00:00". Both spaces have to go.
const toIso = (v) => {
  const s = String(v == null ? '' : v).trim();
  if (!s) return null;
  let t = s.replace(' ', 'T').replace(/\s+(?=[+-]\d\d:?\d\d$)/, '');
  if (!/(Z|[+-]\d\d:?\d\d)$/.test(t)) t += 'Z'; // ASSUMPTION: no offset means UTC
  const d = new Date(t);
  return isNaN(d) ? null : d.toISOString();
};
const iso = toIso;
// Whole address, not the local part. Matching only the local part is wrong in
// BOTH directions: jake.fassora.qa@ scores as a real Pro, and a genuine Pro at
// allison.torres@some-other-domain.com is falsely called internal — which merges
// to 'conflict' against the proven send and permanently disqualifies a real touch.
// EDIT HERE if internal testers are on another domain.
let _dom = 'housecallpro.com';
try { _dom = $env.WAYPOINT_INTERNAL_DOMAIN || _dom; } catch (e) { /* $env blocked */ }
const INTERNAL_DOMAIN = _dom.toLowerCase();
const addr = (email) => {
  const [local, domain] = String(email || '').toLowerCase().split('@');
  return { local: String(local || '').split('+')[0], domain: domain || '' };
};
// 'internal' | 'external' | 'unprovable' — never guess between the last two.
// The DOMAIN decides, not the roster. Roster-first was a live hole: any
// unrostered address on the internal domain (jake.fassora.qa@, a new tester,
// a shared alias) fell through to 'external' => 'route-to-pro', so a guardrailed
// send became a proven one, that Pro's organic Amplitude activity was scored as
// a return, and _promote_warm_start propagated the mechanism CROSS-ORG off a
// touch nobody received. A real Pro is never on the internal domain, so keying
// on the domain cannot produce a false guardrail either.
const classify = (email) => {
  const { local, domain } = addr(email);
  if (!local || !domain) return 'unprovable';
  if (domain === INTERNAL_DOMAIN) return 'internal';
  // A Pro who merely shares a roster local part on their own domain is not
  // provably either way — claim nothing rather than conflict away a real touch.
  return INTERNAL.includes(local) ? 'unprovable' : 'external';
};

const touches = new Map();
for (const item of items) {
  const type = item.json.dataTypeName;
  for (const line of String(item.json.data || '').split('\n')) {
    if (!line.trim()) continue;
    let ev; try { ev = JSON.parse(line); } catch { continue; }
    // Rule 4: no parseable transactionalData => no dimensions at all (sends predating
    // the LCM stamps). Skip. Never fall back to timestamp guessing.
    if (typeof ev.transactionalData !== 'string') continue;
    let d; try { d = JSON.parse(ev.transactionalData); } catch { continue; }
    // Rule 2: arm B is a single pre-selected CONTROL message, not our
    // recommendation. Require a POSITIVE 'A': ==='B' failed OPEN on 'b', 'B ',
    // a missing stamp, or any future arm name — crediting the control's
    // results to our idea, which is the one thing this filter exists to stop.
    if (d.lcmVariant !== 'A') continue;
    const runId = d.lcmRun, proId = ev.userId;
    // TouchOutcomeIn rejects a blank or ':'-bearing natural key, and it 422s the
    // WHOLE batch — so drop the one bad event here rather than lose 500 good rows.
    if (!runId || !proId || runId.includes(':') || proId.includes(':')) continue;
    // Not one of ours (another LCM workstream, or a Pro we never shipped).
    const key = runId + '|' + proId;
    if (!shipped.has(key)) continue;
    const t = touches.get(key) || {
      run_id: runId, pro_id: proId,
      channel: type.startsWith('sms') ? 'sms' : 'email',
      stamped: null, internal: false, external: false, unproven: false,
      sent_at: null, clicked: false, unsubscribed: false,
    };
    // Rule 1: prove route-to-pro or say guardrail. Prefer the stamp if the LCM app sends it.
    if (d.lcmRouting) t.stamped = d.lcmRouting;
    else {
      const who = classify(ev.email);   // sms events carry phoneNumber, not email => 'unprovable'
      if (who === 'internal') t.internal = true;
      else if (who === 'external') t.external = true;
      else t.unproven = true;           // no claim either way — see the routing merge below
    }
    if (type.endsWith('Send')) {
      const at = iso(ev.createdAt);
      if (at && (!t.sent_at || at < t.sent_at)) t.sent_at = at;
    }
    if (type.endsWith('Click')) t.clicked = true;
    if (type.endsWith('Unsubscribe')) t.unsubscribed = true;
    touches.set(key, t);
  }
}

const rows = [...touches.values()].map((t) => {
  // Three-way, NOT two-way. outcomes.merge_routing treats '' as "no claim" (defers
  // to what is stored) but two DIFFERENT claims fail closed to 'conflict'. So an
  // event we cannot prove either way must claim NOTHING — emitting 'guardrail'
  // there would conflict with an earlier proven send and disqualify a real touch.
  const routing = t.stamped
    ? (t.stamped === 'route-to-pro' ? 'route-to-pro' : 'guardrail')
    : t.internal ? 'guardrail'          // proven internal inbox
    : t.external ? 'route-to-pro'       // some event proved a real external recipient
    : '';                               // unprovable (no email on any event): omit and defer
  const row = {
    run_id: t.run_id, pro_id: t.pro_id, source: 'iterable_n8n',
    channel: t.channel, delivered: true,
  };
  if (routing) row.routing = routing;
  if (t.sent_at) row.sent_at = t.sent_at;
  // Assert TRUE only. A later window recomputes from a narrower slice, and a
  // false here would overwrite an already-observed click/unsubscribe. Omitted
  // fields arrive as null, and _apply_flags never lets null erase a value.
  if (t.clicked) row.clicked = true;
  if (t.unsubscribed) row.unsubscribed = true;
  return row;
});

const out = [];
for (let i = 0; i < rows.length; i += CHUNK) out.push({ json: { batch: rows.slice(i, i + CHUNK) } });
return out; // zero rows => zero items => the POST node simply does not run

// For each horizon, re-read the Iterable SEND events from the single UTC day that
// aged past that horizon yesterday. Sends are the only source of truth for the
// anchor timestamp, and re-reading them means no Waypoint read endpoint is needed.
const HORIZONS = [7, 14, 30, 90];
const DAY = 86400000;
const fmt = (d) => d.toISOString().slice(0, 19).replace('T', ' '); // ASSUMPTION: Iterable project timezone is UTC
const out = [];
for (const horizon of HORIZONS) {
  // horizon + 1: measure a day AFTER the window closes, so no touch is scored
  // on a window that is still open when the cron fires.
  const start = new Date(Date.now() - (horizon + 1) * DAY);
  start.setUTCHours(0, 0, 0, 0);
  const end = new Date(start.getTime() + DAY);
  for (const dataTypeName of ['emailSend', 'smsSend']) {
    out.push({ json: { horizon, dataTypeName, startDateTime: fmt(start), endDateTime: fmt(end) } });
  }
}
return out;

// One item per (touch, horizon) that is worth an Amplitude lookup.
// Deliberately duplicates the parse/routing logic in "Build outcomes": n8n Code
// nodes cannot share a module, and two copies of 25 lines beats a shared-code
// sub-workflow nobody can debug. Change both together.
// Option C: start from what WE shipped, not from everything Iterable did.
// The work list is Waypoint's own funnel detail — every Pro that reached a
// verdict in the window. Only winners that were actually handed off could
// possibly have been sent, so anything else in the Iterable window is not ours
// and is dropped here instead of being POSTed as an unattributable row.
const WORKLIST = 'Waypoint work list (sweep)';
const shipped = new Set(
  $(WORKLIST).all()
    .flatMap((i) => (i.json && i.json.pros) || [])
    .filter((p) => p.verdict === 'winner' && p.handed_off)
    .map((p) => p.run_id + '|' + p.pro_id)
);
if (!shipped.size) return [];  // nothing shipped in the window => nothing to match

const INTERNAL = ['allison.torres', 'jake.fassora', 'liann.bielicki'];

// Normalise to a real ISO instant. TWO traps here:
//   * `new Date("2026-08-20 10:00:00")` is VALID in V8 and is read in the
//     PROCESS-LOCAL zone, so a parse-then-fallback never reaches the 'Z' branch
//     for exactly the format we expect. settings.timezone governs cron
//     expressions, not `new Date()` inside a Code node. Offset FIRST.
//   * Iterable writes the offset after a SPACE ("... 10:00:00 +00:00"), and
//     replace(' ', 'T') only replaces the FIRST space — leaving an unparseable
//     "10:00:00 +00:00". Both spaces have to go.
