  const s = String(v == null ? '' : v).trim();
  if (!s) return null;
  let t = s.replace(' ', 'T').replace(/\s+(?=[+-]\d\d:?\d\d$)/, '');
  if (!/(Z|[+-]\d\d:?\d\d)$/.test(t)) t += 'Z'; // ASSUMPTION: no offset means UTC
  const d = new Date(t);
  return isNaN(d) ? null : d.toISOString();
};
const iso = toIso;
// Whole address, not the local part. Matching only the local part is wrong in
// BOTH directions: jake.fassora.qa@ scores as a real Pro, and a genuine Pro at
// allison.torres@some-other-domain.com is falsely called internal — which merges
// to 'conflict' against the proven send and permanently disqualifies a real touch.
// EDIT HERE if internal testers are on another domain.
let _dom = 'housecallpro.com';
try { _dom = $env.WAYPOINT_INTERNAL_DOMAIN || _dom; } catch (e) { /* $env blocked */ }
const INTERNAL_DOMAIN = _dom.toLowerCase();
const addr = (email) => {
  const [local, domain] = String(email || '').toLowerCase().split('@');
  return { local: String(local || '').split('+')[0], domain: domain || '' };
};
// 'internal' | 'external' | 'unprovable' — never guess between the last two.
// The DOMAIN decides, not the roster. Roster-first was a live hole: any
// unrostered address on the internal domain (jake.fassora.qa@, a new tester,
// a shared alias) fell through to 'external' => 'route-to-pro', so a guardrailed
// send became a proven one, that Pro's organic Amplitude activity was scored as
// a return, and _promote_warm_start propagated the mechanism CROSS-ORG off a
// touch nobody received. A real Pro is never on the internal domain, so keying
// on the domain cannot produce a false guardrail either.
const classify = (email) => {
  const { local, domain } = addr(email);
  if (!local || !domain) return 'unprovable';
  if (domain === INTERNAL_DOMAIN) return 'internal';
  // A Pro who merely shares a roster local part on their own domain is not
  // provably either way — claim nothing rather than conflict away a real touch.
  return INTERNAL.includes(local) ? 'unprovable' : 'external';
};

const seen = new Set();
const out = [];
// Skips are silent by nature — count them so a channel quietly measuring
// nothing (e.g. SMS with no lcmRouting stamp) is visible in the run log.
const skipped = { guardrail: 0, unprovable: 0 };
for (const item of items) {
  const horizon = item.json.horizon;
  const channel = item.json.dataTypeName.startsWith('sms') ? 'sms' : 'email';
  for (const line of String(item.json.data || '').split('\n')) {
    if (!line.trim()) continue;
    let ev; try { ev = JSON.parse(line); } catch { continue; }
    if (typeof ev.transactionalData !== 'string') continue; // rule 4
    let d; try { d = JSON.parse(ev.transactionalData); } catch { continue; }
    if (d.lcmVariant !== 'A') continue;                     // rule 2 (positive check: fails CLOSED)
    const run_id = d.lcmRun, pro_id = ev.userId;
    if (!run_id || !pro_id || run_id.includes(':') || pro_id.includes(':')) continue; // 422s the whole batch otherwise
    const sent_at = iso(ev.createdAt);
    if (!sent_at) continue;                                 // rule 5: no true anchor, no measurement
    // Rule 1: only a PROVEN real-Pro send may be scored. A guardrailed send is
    // delivered to an internal inbox, but Amplitude would still report that
    // Pro's organic activity — that is a manufactured return. Skip entirely.
    // Same three-way classification as "Build outcomes". An SMS event carries
    // phoneNumber, not email, so absence of an address is UNPROVABLE, not proof
    // of a guardrail — reading it as guardrail silently dropped every SMS touch
    // from every horizon, with no error and no log line.
    const routing = d.lcmRouting
      ? (d.lcmRouting === 'route-to-pro' ? 'route-to-pro' : 'guardrail')
      : ({ internal: 'guardrail', external: 'route-to-pro', unprovable: '' })[classify(ev.email)];
    if (routing !== 'route-to-pro') { skipped[routing || 'unprovable']++; continue; }
    if (!shipped.has(run_id + '|' + pro_id)) continue;  // not one of ours
    const key = horizon + '|' + run_id + '|' + pro_id;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: { horizon, run_id, pro_id, channel, sent_at } });
  }
}
console.log(`eligible=${out.length} skipped_guardrail=${skipped.guardrail} skipped_unprovable=${skipped.unprovable}`);
return out;

// The qualifying active-use predicate is a NAMED PLACEHOLDER, not a guess.
// The canonical Amplitude active-use event contract is still open (TODOS.md),
// so this refuses to run rather than inventing a proxy metric.
// EDIT HERE. Comma-separated Amplitude event names that count as "the Pro came
// back and used the app". No default on purpose: the canonical active-use event
// contract is still open (TODOS.md), and a guessed proxy metric would quietly
// teach the loop the wrong thing. An n8n env var of the same name overrides this
// if you'd rather keep it off the canvas.
const ACTIVE_USE_EVENTS = '';
let configured = ACTIVE_USE_EVENTS;
try { configured = $env.AMPLITUDE_ACTIVE_USE_EVENTS || ACTIVE_USE_EVENTS; } catch (e) { /* $env blocked */ }
const EVENTS = String(configured).split(',').map((s) => s.trim()).filter(Boolean);
if (!EVENTS.length) {
  throw new Error('Set ACTIVE_USE_EVENTS at the top of this node (or the AMPLITUDE_ACTIVE_USE_EVENTS env var). The canonical active-use event contract is undefined (TODOS.md) — refusing to guess a qualifying event.');
}
const CHUNK = 500;
const DAY = 86400000;
// Must match &limit= on the 'Amplitude user activity' node.
const ACTIVITY_LIMIT = 1000;

// Normalise to a real ISO instant. TWO traps here:
//   * `new Date("2026-08-20 10:00:00")` is VALID in V8 and is read in the
//     PROCESS-LOCAL zone, so a parse-then-fallback never reaches the 'Z' branch
//     for exactly the format we expect. settings.timezone governs cron
//     expressions, not `new Date()` inside a Code node. Offset FIRST.
//   * Iterable writes the offset after a SPACE ("... 10:00:00 +00:00"), and
//     replace(' ', 'T') only replaces the FIRST space — leaving an unparseable
//     "10:00:00 +00:00". Both spaces have to go.
const toIso = (v) => {
  const s = String(v == null ? '' : v).trim();
  if (!s) return null;
  let t = s.replace(' ', 'T').replace(/\s+(?=[+-]\d\d:?\d\d$)/, '');
  if (!/(Z|[+-]\d\d:?\d\d)$/.test(t)) t += 'Z'; // ASSUMPTION: no offset means UTC
  const d = new Date(t);
  return isNaN(d) ? null : d.toISOString();
};
const evTime = (v) => { const i = toIso(v); return i ? Date.parse(i) : NaN; };

const rows = [];
let unmeasured = 0;
for (let i = 0; i < items.length; i++) {
  const touch = $('Eligible touches').itemMatching(i).json;
  const sent = Date.parse(touch.sent_at);              // rule 5: the TRUE Iterable send time
  const until = sent + touch.horizon * DAY;
  // A FAILED lookup is not a measured negative. With onError=continueRegular
  // Output the node emits the item carrying an `error` instead of `events`,
  // and `|| []` would have scored that as returned:false — writing a fabricated
  // measured fact for a Pro we never actually looked up. Skip it; the row keeps
  // its NULL and a later night can still fill it.
  const payload = items[i].json;
  if (payload.error || !Array.isArray(payload.events)) { unmeasured++; continue; }
  const events = payload.events;
  // useractivity returns the most-recent LIMIT events with no time filter. If
  // it truncated AND the oldest event we got back is newer than the send, the
  // window is only partly covered and a `false` here would be fabricated, not
  // measured. Leave it NULL — a later night can still fill it.
  const oldest = events.reduce((m, e) => Math.min(m, evTime(e.event_time) || Infinity), Infinity);
  if (events.length >= ACTIVITY_LIMIT && isFinite(oldest) && oldest > sent) {
    unmeasured++;
    continue;
  }
  const returned = events.some((e) => {
    if (!EVENTS.includes(e.event_type)) return false;
    const t = evTime(e.event_time);
    return !isNaN(t) && t >= sent && t <= until;
  });
  rows.push({
    run_id: touch.run_id, pro_id: touch.pro_id, source: 'iterable_n8n',
    channel: touch.channel, routing: 'route-to-pro', sent_at: touch.sent_at,
    ['returned_' + touch.horizon + 'd']: returned,
  });
}

console.log(`scored=${rows.length} unmeasured_lookup_failures=${unmeasured}`);
const out = [];
for (let i = 0; i < rows.length; i += CHUNK) out.push({ json: { batch: rows.slice(i, i + CHUNK) } });
return out;
